<?php
/**
 * DooFinder Polylang methods.
 *
 * @package Doofinder\WP\Multilanguage
 */

namespace Doofinder\WP\Multilanguage;

use Doofinder\WP\Helpers\Helpers;

/**
 * Handles the languages generated by the Polylang plugin (free version).
 *
 * Returns data in the same formats as the WPML handler, so the rest of the
 * plugin can work with any of them without knowing which one is active.
 *
 * Polylang loads its API (`pll_*` functions and `PLL()`) on `plugins_loaded`
 * with priority 1, after this plugin is bootstrapped, so the languages are
 * read lazily, the first time they are needed.
 */
class Polylang extends Language_Plugin implements I18n_Handler {

	/**
	 * Cached list of languages, keyed by Polylang language slug.
	 * Null until Polylang's API is available and the list has been read.
	 *
	 * @var array|null
	 */
	private $languages = null;

	/**
	 * Language slug the queries are filtered by after `switch_language()`.
	 * Empty when no language has been switched to.
	 *
	 * @var string
	 */
	private $query_language = '';

	/**
	 * Check if the Polylang plugin is active.
	 *
	 * Only the constant can be checked this early: the `pll_*` functions are
	 * not loaded until Polylang initializes.
	 *
	 * @return bool
	 */
	public static function is_plugin_active() {
		return defined( 'POLYLANG_VERSION' );
	}

	/**
	 * Read the languages configured in Polylang.
	 *
	 * Each language has the same keys as the WPML handler ones: name, english_name,
	 * code, active, default, prefix and locale. Inactive languages are skipped.
	 *
	 * @return array List of languages keyed by language code (Polylang slug).
	 */
	private function load_languages() {
		if ( null !== $this->languages ) {
			return $this->languages;
		}

		// Polylang is not initialized yet. Don't cache, so it's read again later.
		if ( ! function_exists( 'pll_languages_list' ) || ! function_exists( 'pll_default_language' ) ) {
			return array();
		}

		$default_language = \pll_default_language();
		$languages        = array();

		foreach ( \pll_languages_list( array( 'fields' => '' ) ) as $language ) {
			if ( isset( $language->active ) && false === $language->active ) {
				continue;
			}

			$is_default = ( $language->slug === $default_language );

			$languages[ $language->slug ] = array(
				'name'         => $language->name,
				'english_name' => $language->name,
				'code'         => $language->slug,
				'active'       => true,
				'default'      => $is_default,
				'prefix'       => $is_default ? '' : $language->slug,
				'locale'       => $language->locale,
			);
		}

		$this->languages = $languages;

		return $this->languages;
	}

	/**
	 * Get the slug of the language Polylang is using for the current request.
	 *
	 * In REST requests Polylang only sets the language from the `lang` parameter,
	 * so as a fallback it's taken from the URL (e.g. the indexing status callback
	 * is called on `/es/?rest_route=...`).
	 *
	 * @return string Language slug, or empty string if none (e.g. "All languages" in the admin).
	 */
	private function get_request_language() {
		if ( function_exists( 'pll_current_language' ) ) {
			$language = \pll_current_language();
			if ( $language ) {
				return $language;
			}
		}

		if ( ! is_admin() && function_exists( 'PLL' ) && isset( \PLL()->links_model ) ) {
			$language = \PLL()->links_model->get_language_from_url();
			if ( $language ) {
				return $language;
			}
		}

		return '';
	}

	/**
	 * Inherited from Language_Plugin.
	 *
	 * @inheritdoc
	 */
	public function get_languages() {
		return $this->load_languages();
	}

	/**
	 * Inherited from Language_Plugin.
	 *
	 * Same format as the WPML handler: keyed by locale (e.g. 'es_ES'), with the
	 * language code and name as value.
	 *
	 * @inheritdoc
	 */
	public function get_formatted_languages() {
		$formatted_languages = array();

		foreach ( $this->load_languages() as $language ) {
			$formatted_languages[ $language['locale'] ] = array(
				'code'            => $language['code'],
				'translated_name' => $language['name'],
			);
		}

		return $formatted_languages;
	}

	/**
	 * Inherited from Language_Plugin.
	 *
	 * @inheritdoc
	 */
	public function get_active_language() {
		// "All languages" in the admin returns an empty value. As with WPML,
		// it's treated as if no language was selected.
		return function_exists( 'pll_current_language' ) ? (string) \pll_current_language() : '';
	}

	/**
	 * Inherited from Language_Plugin.
	 *
	 * Same behavior as the WPML handler: empty string for the base language,
	 * the language code for any other one and false when there's no language.
	 *
	 * @inheritdoc
	 */
	public function get_current_language() {
		$language  = $this->get_request_language();
		$languages = $this->load_languages();

		if ( ! $language || ! isset( $languages[ $language ] ) ) {
			return false;
		}

		if ( $language === $this->get_base_language() ) {
			return '';
		}

		return $language;
	}

	/**
	 * Inherited from Language_Plugin.
	 *
	 * @inheritdoc
	 */
	public function get_default_language() {
		$languages = $this->load_languages();
		return $languages[ $this->get_base_language() ] ?? '';
	}

	/**
	 * Inherited from Language_Plugin.
	 *
	 * @inheritdoc
	 */
	public function get_base_language() {
		return function_exists( 'pll_default_language' ) ? (string) \pll_default_language() : '';
	}

	/**
	 * Get the locale of the base (default) language, e.g. 'en_US'.
	 * Falls back to the WordPress locale if Polylang is not ready.
	 *
	 * @return string
	 */
	public function get_base_locale() {
		$languages = $this->load_languages();
		return $languages[ $this->get_base_language() ]['locale'] ?? get_locale();
	}

	/**
	 * Inherited from Language_Plugin.
	 *
	 * @param string $locale The locale string with underscore to search for (e.g. 'en_US', 'es_ES', 'zh_CN').
	 *
	 * @inheritdoc
	 */
	public function get_lang_code_by_locale( $locale ) {
		$locale_lowercase = strtolower( $locale );
		foreach ( $this->load_languages() as $language ) {
			if ( strtolower( $language['locale'] ) === $locale_lowercase ) {
				return $language['code'];
			}
		}

		return $locale;
	}

	/**
	 * Get the locale (e.g. 'es_ES') of a language code. Falls back to the base locale.
	 *
	 * @param string $lang_code Language code (Polylang slug).
	 *
	 * @return string
	 */
	public function get_locale_by_lang_code( $lang_code ) {
		$languages = $this->load_languages();
		return $languages[ $lang_code ]['locale'] ?? $this->get_base_locale();
	}

	/**
	 * Inherited from Language_Plugin.
	 *
	 * @inheritdoc
	 *
	 * @param string $language Language code (Polylang slug).
	 *
	 * @return string
	 */
	public function get_home_url( $language ) {
		if ( ! function_exists( 'pll_home_url' ) ) {
			return get_bloginfo( 'url' );
		}

		return (string) \pll_home_url( $language );
	}

	/**
	 * Inherited from Language_Plugin.
	 *
	 * Variations can't be translated with Polylang free, so they take
	 * the language of their parent product.
	 *
	 * @param int $post_id Post ID.
	 *
	 * @inheritdoc
	 */
	public function get_post_language( $post_id ) {
		if ( ! function_exists( 'pll_get_post_language' ) ) {
			return '';
		}

		if ( 'product_variation' === get_post_type( $post_id ) ) {
			$post_id = wp_get_post_parent_id( $post_id );
		}

		return $post_id ? (string) \pll_get_post_language( $post_id ) : '';
	}

	/**
	 * Inherited from Language_Plugin.
	 *
	 * Sets Polylang's current language and filters the queries of translatable post
	 * types by it. Polylang doesn't filter WooCommerce REST API queries by itself.
	 *
	 * @param string $lang_code Language code (Polylang slug).
	 *
	 * @inheritdoc
	 */
	public function switch_language( $lang_code ) {
		if ( ! function_exists( 'PLL' ) || ! isset( \PLL()->model ) ) {
			return;
		}

		$language = \PLL()->model->get_language( $lang_code );
		if ( ! $language ) {
			return;
		}

		\PLL()->curlang       = $language;
		$this->query_language = $language->slug;

		if ( false === has_action( 'pre_get_posts', array( $this, 'filter_query_by_language' ) ) ) {
			add_action( 'pre_get_posts', array( $this, 'filter_query_by_language' ) );
		}
	}

	/**
	 * Inherited from Language_Plugin.
	 *
	 * @inheritdoc
	 */
	public function switch_to_all_languages() {
		$this->query_language = '';

		if ( function_exists( 'PLL' ) ) {
			\PLL()->curlang = null;
		}
	}

	/**
	 * Filter a query by the language set in `switch_language()`.
	 *
	 * Uses the `lang` query var of Polylang's `language` taxonomy. Queries that
	 * already ask for a language, or that include non-translatable post types
	 * (e.g. product variations), are left untouched.
	 *
	 * @param \WP_Query $query The query.
	 *
	 * @return void
	 */
	public function filter_query_by_language( $query ) {
		if ( '' === $this->query_language || ! function_exists( 'pll_is_translated_post_type' ) ) {
			return;
		}

		if ( '' !== (string) $query->get( 'lang' ) ) {
			return;
		}

		$post_types = $query->get( 'post_type' );
		$post_types = empty( $post_types ) ? array( 'post' ) : (array) $post_types;

		foreach ( $post_types as $post_type ) {
			if ( 'any' === $post_type || ! \pll_is_translated_post_type( $post_type ) ) {
				return;
			}
		}

		$query->set( 'lang', $this->query_language );
	}

	/**
	 * Retrieve the name of the WordPress option for the current language.
	 *
	 * Same behavior as the WPML handler: the base option name for the base
	 * language (or no language), and the base name with the language code
	 * as suffix for any other one.
	 *
	 * @param string $base Option name without the language suffix.
	 *
	 * @return string
	 */
	public function get_option_name( $base ) {
		$language_code = $this->get_active_language();
		if ( ! $language_code ) {
			return $base;
		}

		if ( $language_code === $this->get_base_language() ) {
			return $base;
		}

		$language_code = strtolower( Helpers::format_locale_to_hyphen( $language_code ) );

		return "{$base}_{$language_code}";
	}
}
